def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    # Exploit non-retaliators: opponent cooperated after our defection at least twice
    failures = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i + 1][1] == 'C':
            failures += 1
    if failures >= 2:
        return 'D'

    opp_def_total = 0
    for _, opp in history:
        if opp == 'D':
            opp_def_total += 1
    opp_def_rate = opp_def_total / n

    opp_def_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_def_run += 1
        else:
            break

    my_def_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_def_run += 1
        else:
            break

    last_my, last_opp = history[-1]

    # Long defection run: probe with cooperation to break mutual defection
    if opp_def_run >= 3:
        if last_my == 'C':
            if n >= 2 and history[-2][0] == 'C':
                return 'D'
            return 'C'
        else:
            if my_def_run >= 4:
                return 'C'
            return 'D'

    # Forgive when opponent is mostly cooperative
    if opp_def_rate <= 0.15:
        if n % 15 == 0 and rng.random() < 0.2:
            return 'D'
        return 'C'

    # Defect mostly against frequent defectors
    if opp_def_rate >= 0.6:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Default: Tit-for-Tat with forgiveness
    if last_opp == 'C':
        return 'C'
    else:
        if last_my == 'C':
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            if opp_def_run >= 2 and rng.random() < 0.3:
                return 'C'
            return 'D'
